<div class="section-heading"><div><div class="eyebrow">Barbearia</div><h1>Metas da equipe</h1><p class="text-secondary mb-0">Acompanhe produção, produtos, ticket médio e evolução mensal por profissional.</p></div><form class="d-flex gap-2" method="get"><select class="form-select" name="month"><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>" <?=$m===$month?'selected':''?>><?=str_pad((string)$m,2,'0',STR_PAD_LEFT)?></option><?php endfor;?></select><input class="form-control" style="width:110px" type="number" name="year" value="<?=$year?>"><button class="btn btn-outline-primary">Ver</button></form></div>
<div class="row g-3"><?php foreach($rows as $r):$total=(float)$r['service_revenue']+(float)$r['product_revenue'];$count=(int)$r['service_count'];$ticket=$count?((float)$r['service_revenue']/$count):0;$target=(float)($r['revenue_target']??0);$progress=$target>0?min(100,round($total/$target*100)):0;?><div class="col-xl-6"><div class="card h-100"><div class="card-body"><div class="d-flex justify-content-between"><div><div class="eyebrow">Profissional</div><h2 class="h5"><?=htmlspecialchars($r['name'])?></h2></div><strong><?=$progress?>%</strong></div><div class="progress mb-3" role="progressbar" aria-valuenow="<?=$progress?>" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width:<?=$progress?>%"></div></div><div class="row g-2 small"><div class="col-6"><span class="text-secondary">Produção</span><strong class="d-block">R$ <?=number_format($total,2,',','.')?></strong></div><div class="col-6"><span class="text-secondary">Meta receita</span><strong class="d-block">R$ <?=number_format($target,2,',','.')?></strong></div><div class="col-6"><span class="text-secondary">Serviços</span><strong class="d-block"><?=$count?> / <?=(int)($r['services_target']??0)?></strong></div><div class="col-6"><span class="text-secondary">Produtos</span><strong class="d-block">R$ <?=number_format((float)$r['product_revenue'],2,',','.')?></strong></div><div class="col-6"><span class="text-secondary">Ticket serviços</span><strong class="d-block">R$ <?=number_format($ticket,2,',','.')?></strong></div><div class="col-6"><span class="text-secondary">Meta ticket</span><strong class="d-block">R$ <?=number_format((float)($r['ticket_target']??0),2,',','.')?></strong></div></div><?php if($canManage):?><hr><form method="post" action="/barber/goals" class="row g-2"><?=\App\Core\CSRF::field()?><input type="hidden" name="professional_id" value="<?=(int)$r['id']?>"><input type="hidden" name="year" value="<?=$year?>"><input type="hidden" name="month" value="<?=$month?>"><div class="col-6"><label class="form-label small">Meta receita</label><input class="form-control form-control-sm" type="number" step=".01" min="0" name="revenue_target" value="<?=htmlspecialchars((string)($r['revenue_target']??0))?>"></div><div class="col-6"><label class="form-label small">Meta atendimentos</label><input class="form-control form-control-sm" type="number" min="0" name="services_target" value="<?=(int)($r['services_target']??0)?>"></div><div class="col-6"><label class="form-label small">Meta produtos</label><input class="form-control form-control-sm" type="number" step=".01" min="0" name="products_target" value="<?=htmlspecialchars((string)($r['products_target']??0))?>"></div><div class="col-6"><label class="form-label small">Meta ticket</label><input class="form-control form-control-sm" type="number" step=".01" min="0" name="ticket_target" value="<?=htmlspecialchars((string)($r['ticket_target']??0))?>"></div><div class="col-12"><button class="btn btn-sm btn-primary w-100">Salvar meta</button></div></form><?php endif;?></div></div></div><?php endforeach;?></div>
